for x in r['rows']:
 i=x['env'];good=(height[:,i]>=.23)&(height[:,i]<=.33)&(cos[:,i]>=math.cos(math.radians(20)))&t['alive'][:,i]&x['valid_ground_start'];hold=0;maximum=0;first=None
 for k,value in enumerate(good):
  hold=hold+1 if value else 0;maximum=max(maximum,hold)
